('CHE-STR-015','Cobra suave','core',NULL,'estiramiento','principiante','Colchoneta','Extensión suave del tronco y región anterior abdominal.','Desde prono, eleva el pecho con apoyo de antebrazos o manos sin comprimir la zona lumbar.','Bloquear codos; dolor lumbar; elevar hombros','Usa antebrazos si necesitas menos extensión.','movilidad','bilateral','sagital','columna','Esfinge','Cobra suave','Cobra con mayor extensión tolerable','Esfinge',ARRAY['estiramientos','core','movilidad']::text[],ARRAY['movilidad','vuelta calma']::text[],true,true,'principiante','bajo',true),
('CHE-STR-016','Respiración diafragmática tumbado','core',NULL,'movilidad','principiante','Colchoneta','Ejercicio de respiración para reducir activación al finalizar la sesión.','Tumbado boca arriba, inspira por nariz expandiendo abdomen y costillas bajas; espira lentamente sin tensión.','Elevar hombros; respiración rápida; forzar inhalación','Realiza 5-10 ciclos lentos y cómodos.','movilidad','bilateral','multiplanar','diafragma','Respiración natural','Exhalación prolongada','Respiración 4-6 segundos','Respiración natural',ARRAY['estiramientos','respiracion','vuelta_calma']::text[],ARRAY['respiración','recuperación']::text[],true,true,'principiante','bajo',true)

on conflict (codigo_interno) where codigo_interno is not null do update set
  nombre=excluded.nombre,
  grupo_muscular=excluded.grupo_muscular,
  grupo_secundario=excluded.grupo_secundario,
  categoria=excluded.categoria,
  dificultad=excluded.dificultad,
  material=excluded.material,
  descripcion=excluded.descripcion,
  tecnica=excluded.tecnica,
  errores_frecuentes=excluded.errores_frecuentes,
  consejos=excluded.consejos,
  tipo_movimiento=excluded.tipo_movimiento,
  lateralidad=excluded.lateralidad,
  plano_movimiento=excluded.plano_movimiento,
  articulacion_principal=excluded.articulacion_principal,
  variante_facil=excluded.variante_facil,
  progresion=excluded.progresion,
  variante_avanzada=excluded.variante_avanzada,
  regresion=excluded.regresion,
  etiquetas=excluded.etiquetas,
  objetivos=excluded.objetivos,
  apto_casa=excluded.apto_casa,
  apto_gimnasio=excluded.apto_gimnasio,
  nivel_tecnico=excluded.nivel_tecnico,
  riesgo_lesion=excluded.riesgo_lesion,
  activo=excluded.activo,
  updated_at=now();
